// VTABLE (vtable) and VIRTUAL POINTER (vptr)
class Base {
    // Object Memory Layout typically starts with vptr:
    // [ vptr (8 bytes) | data_B (4 bytes) ]
    int data_B;
public:
    virtual void f1() = 0;
    virtual void f2() {} // Vtable entry 1
};

class Derived : public Base {
    int data_D;
public:
    void f1() override {} // Vtable entry 0
    void f2() override {}
};

Base* p = new Derived();
// Runtime dispatch (vptr lookup):
// 1. Get vptr from object (offset 0).
// 2. Index into vtable array (f2 is index 1).
// 3. Call function pointer at vtable[1].
// p->f2() conceptually translates to:
// (*((p->vptr)[1]))(p);
delete p;
